module optimal_cache(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] c,\n    input wire [4:0] a,\n    input wire [4:0] obj_addr,\n    input wire [3:0] obj_data,\n    input wire obj_write,\n    output reg [7:0] miss_count,\n    output reg done\n);\n    \n    // Parameters\n    localparam [3:0] MAX_CACHE = 4;\n    localparam [4:0] MAX_SEQ = 16;\n    \n    // State encoding\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] CHECK = 3'd2;\n    localparam [2:0] MISS = 3'd3;\n    localparam [2:0] ADD = 3'd4;\n    localparam [2:0] EVICT = 3'd5;\n    localparam [2:0] NEXT = 3'd6;\n    localparam [2:0] DONE_STATE = 3'd7;\n    \n    // Sequence memory\n    reg [3:0] seq [0:15];\n    \n    // Cache\n    reg [3:0] cache [0:3];\n    reg valid [0:3];\n    \n    // Registers\n    reg [4:0] current_index;\n    reg [2:0] occupied;\n    reg [2:0] state, next_state;\n    \n    // Combinational signals\n    wire hit;\n    reg [2:0] hit_slot;\n    wire has_empty;\n    reg [2:0] empty_slot;\n    wire [4:0] next_use [0:3];\n    reg [2:0] evict_slot;\n    wire [4:0] max_next_use;\n    \n    integer i, j;\n    \n    // Write sequence memory\n    always @(posedge clk) begin\n        if (obj_write) begin\n            seq[obj_addr] <= obj_data;\n        end\n    end\n    \n    // Hit detection\n    always @(*) begin\n        hit = 1'b0;\n        hit_slot = 3'd0;\n        for (i = 0; i < 4; i = i + 1) begin\n            if (i < c && valid[i] && cache[i] == seq[current_index]) begin\n                hit = 1'b1;\n                hit_slot = i;\n            end\n        end\n    end\n    \n    // Empty slot detection\n    always @(*) begin\n        has_empty = 1'b0;\n        empty_slot = 3'd0;\n        for (i = 0; i < 4; i = i + 1) begin\n            if (i < c && !valid[i] && !has_empty) begin\n                has_empty = 1'b1;\n                empty_slot = i;\n            end\n        end\n    end\n    \n    // Next use computation\n    always @(*) begin\n        for (i = 0; i < 4; i = i + 1) begin\n            next_use[i] = 5'd0;\n            if (i < c && valid[i]) begin\n                next_use[i] = 5'd31;\n                for (j = current_index + 1; j < 16; j = j + 1) begin\n                    if (j < a && seq[j] == cache[i] && next_use[i] == 5'd31) begin\n                        next_use[i] = j;\n                    end\n                end\n            end\n        end\n    end\n    \n    // Evict slot selection\n    always @(*) begin\n        max_next_use = 5'd0;\n        evict_slot = 3'd0;\n        for (i = 0; i < 4; i = i + 1) begin\n            if (i < c && valid[i] && next_use[i] > max_next_use) begin\n                max_next_use = next_use[i];\n                evict_slot = i;\n            end\n        end\n    end\n    \n    // State register and sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_index <= 5'd0;\n            occupied <= 3'd0;\n            miss_count <= 8'd0;\n            done <= 1'b0;\n            for (i = 0; i < 4; i = i + 1) begin\n                cache[i] <= 4'd0;\n                valid[i] <= 1'b0;\n            end\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                INIT: begin\n                    occupied <= 3'd0;\n                    miss_count <= 8'd0;\n                    current_index <= 5'd0;\n                    for (i = 0; i < 4; i = i + 1) begin\n                        valid[i] <= 1'b0;\n                        cache[i] <= 4'd0;\n                    end\n                end\n                \n                ADD: begin\n                    cache[empty_slot] <= seq[current_index];\n                    valid[empty_slot] <= 1'b1;\n                    occupied <= occupied + 3'd1;\n                end\n                \n                EVICT: begin\n                    cache[evict_slot] <= seq[current_index];\n                    valid[evict_slot] <= 1'b1;\n                end\n                \n                NEXT: begin\n                    current_index <= current_index + 5'd1;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n                \n                default: ;\n            endcase\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        \n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = INIT;\n                end\n            end\n            \n            INIT: begin\n                next_state = CHECK;\n            end\n            \n            CHECK: begin\n                if (hit) begin\n                    next_state = NEXT;\n                end else begin\n                    next_state = MISS;\n                end\n            end\n            \n            MISS: begin\n                if (has_empty) begin\n                    next_state = ADD;\n                end else begin\n                    next_state = EVICT;\n                end\n            end\n            \n            ADD: begin\n                next_state = NEXT;\n            end\n            \n            EVICT: begin\n                next_state = NEXT;\n            end\n            \n            NEXT: begin\n                if (current_index + 5'd1 < a) begin\n                    next_state = CHECK;\n                end else begin\n                    next_state = DONE_STATE;\n                end\n            end\n            \n            DONE_STATE: begin\n                next_state = IDLE;\n            end\n            \n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // Increment miss_count on ADD or EVICT\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            miss_count <= 8'd0;\n        end else begin\n            if (state == ADD || state == EVICT) begin\n                miss_count <= miss_count + 8'd1;\n            end\n        end\n    end\n    \n    // Clear done when starting new operation\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n        end else begin\n            if (state == IDLE && start) begin\n                done <= 1'b0;\n            end\n        end\n    end\n    \nendmodule